#!/usr/bin/env node
// Compile the legacy SPA shell + per-page templates into render functions.
//
//   web/static/legacy/index.html      -> app.render.js  (root render + cards chunk)
//   web/static/legacy/pages/*.html    -> pages/<group>.render.js (lazy page chunks)
//   pages/pages.manifest.json         -> page -> group/file/template hash
//
// The generated files are committed; production never runs Node.
// Run `npm install` once, then `npm run build` after editing index.html/pages/*.html.
import { createHash } from 'node:crypto'
import fs from 'node:fs'
import path from 'node:path'
import { compile, parse } from '@vue/compiler-dom'
import { fileURLToPath } from 'node:url'

const here = path.dirname(fileURLToPath(import.meta.url))
const repo = path.resolve(here, '../..')
const legacyDir = path.join(repo, 'web/static/legacy')
const indexFile = path.join(legacyDir, 'index.html')
const pagesDir = path.join(legacyDir, 'pages')
const vueRuntime = path.join(legacyDir, 'lib/vue.global.prod.js')
const compilerVersion = JSON.parse(fs.readFileSync(path.join(here, 'node_modules/@vue/compiler-dom/package.json'), 'utf8')).version

// Page -> lazy chunk group. `cards` is in the initial app.render.js.
const GROUPS = {
  likes: ['likes', 'mutual', 'liked_me', 'my_likes', 'reported_messages', 'message_thread'],
  home: ['home', 'my_activities', 'my_groups'],
  profile: ['profile', 'password', 'profile_detail', 'profile_edit', 'points'],
  detail: ['user_detail'],
  group: ['group_admin', 'group_detail', 'group_roster', 'checkin', 'group_select',
    'group_result', 'onetoone_result', 'activity_detail', 'points_admin'],
}

function findApp (node, out = []) {
  if (!node || typeof node !== 'object') return out
  if (node.type === 1 && Array.isArray(node.props)) {
    const id = node.props.find((p) => p.type === 6 && p.name === 'id')
    if (id && id.value && id.value.content === 'app') out.push(node)
  }
  if (Array.isArray(node.children)) for (const child of node.children) findApp(child, out)
  return out
}

function templateOf (html, container) {
  const kids = container.children.filter(Boolean)
  if (!kids.length) throw new Error('#app is empty')
  return html.slice(kids[0].loc.start.offset, kids[kids.length - 1].loc.end.offset)
}

function compileRender (template, label) {
  const result = compile(template, {
    mode: 'module',
    prefixIdentifiers: true,
    hoistStatic: true,
    cacheHandlers: true,
    comments: false,
  })
  let code = result.code
  const importMatch = code.match(/^import \{([\s\S]*?)\} from "vue"\s*/m)
  if (!importMatch) throw new Error(`${label}: compiler output has no vue import to rewrite`)
  const bindings = importMatch[1].replace(/\s+/g, ' ').replace(/ as /g, ': ').trim()
  code = code.replace(importMatch[0], `const { ${bindings} } = Vue;\n`)
  code = code.replace(/export function render\(/, 'function render(')
  if (/^\s*(import|export)\s/m.test(code)) throw new Error(`${label}: compiler output still contains ESM syntax`)
  return code
}

function header (kind, name, template) {
  const hash = createHash('sha256').update(template).digest('hex')
  return { hash, size: Buffer.byteLength(template), text: `/* generated by tools/spa_precompile; vue=${compilerVersion} ${kind}=${name} template-sha256=${hash} template-size=${Buffer.byteLength(template)} */\n` }
}

function wrapChunk (code, assign) {
  return `(function () {\n'use strict';\nif (typeof Vue === 'undefined') {\n  try { console.error('[yxq] render chunk skipped: Vue runtime missing'); } catch (e) {}\n  return;\n}\n${code}\n${assign}\n})();\n`
}

function build () {
  const html = fs.readFileSync(indexFile, 'utf8')
  const app = findApp(parse(html, { comments: true }))[0]
  const rootTemplate = templateOf(html, app)
  const files = new Map()
  const pages = new Map()

  for (const file of fs.readdirSync(pagesDir).filter((f) => f.endsWith('.html')).sort()) {
    const name = file.slice(0, -'.html'.length)
    const template = fs.readFileSync(path.join(pagesDir, file), 'utf8').trim()
    pages.set(name, { template, ...header('page', name, template) })
  }
  const known = new Set(['cards', ...Object.values(GROUPS).flat()])
  for (const name of pages.keys()) if (!known.has(name)) throw new Error('page has no chunk group: ' + name)
  for (const name of known) if (!pages.has(name)) throw new Error('chunk group references missing page: ' + name)

  // Root chunk: root render + the initial cards page render.
  const rootHeader = header('root', '#app', rootTemplate)
  const rootCode = compileRender(rootTemplate, 'root')
  const cards = pages.get('cards')
  const cardsCode = compileRender(cards.template, 'cards').replace(/function render\(/, 'function cardsRender(')
  const rootChunk = `/* generated by tools/spa_precompile/precompile.mjs; vue=${compilerVersion} root template-sha256=${rootHeader.hash} template-size=${rootHeader.size} cards template-sha256=${cards.hash} template-size=${cards.size} */\n` +
    `(function () {\n'use strict';\nif (typeof Vue === 'undefined') {\n  try { console.error('[yxq] render skipped: Vue runtime missing'); } catch (e) {}\n  return;\n}\n` +
    `${rootCode}\nwindow.__YXQ_RENDER__ = render;\n` +
    `(function () {\n${cardsCode}\nwindow.__YXQ_PAGES__ = window.__YXQ_PAGES__ || {};\nwindow.__YXQ_PAGES__['cards'] = cardsRender;\n})();\n})();\n`
  files.set('app.render.js', rootChunk)

  const manifest = {
    generator: 'tools/spa_precompile/precompile.mjs',
    vue: compilerVersion,
    root: {
      file: 'app.render.js',
      templateSha256: rootHeader.hash,
      templateSize: rootHeader.size,
      bytes: Buffer.byteLength(rootChunk),
      sha256: createHash('sha256').update(rootChunk).digest('hex'),
    },
    initial: ['cards'],
    groups: {},
    pages: {
      cards: { group: 'initial', file: 'app.render.js', templateSha256: cards.hash, templateSize: cards.size },
    },
  }

  for (const [group, names] of Object.entries(GROUPS)) {
    let body = ''
    const groupPages = {}
    for (const name of names) {
      const page = pages.get(name)
      const code = compileRender(page.template, name)
      body += `\n(function () {\n${code}\nwindow.__YXQ_PAGES__ = window.__YXQ_PAGES__ || {};\nwindow.__YXQ_PAGES__['${name}'] = render;\n})();\n`
      groupPages[name] = { templateSha256: page.hash, templateSize: page.size }
      manifest.pages[name] = { group, file: `pages/${group}.render.js`, ...groupPages[name] }
    }
    const text = `/* generated by tools/spa_precompile; vue=${compilerVersion} group=${group} pages=${names.join(',')} */\n` +
      `(function () {\n'use strict';\nif (typeof Vue === 'undefined') {\n  try { console.error('[yxq] page chunk skipped: Vue runtime missing'); } catch (e) {}\n  return;\n}\n${body}})();\n`
    files.set(`pages/${group}.render.js`, text)
    manifest.groups[group] = {
      file: `pages/${group}.render.js`,
      pages: names,
      bytes: Buffer.byteLength(text),
      sha256: createHash('sha256').update(text).digest('hex'),
    }
  }

  const manifestText = JSON.stringify(manifest, null, 2) + '\n'
  files.set('pages/pages.manifest.json', manifestText)
  return { files, manifest }
}

const { files, manifest } = build()
const check = process.argv.includes('--check')

if (check) {
  const problems = []
  for (const [rel, want] of files) {
    const p = path.join(legacyDir, rel)
    if (!fs.existsSync(p)) problems.push(`${rel}: missing`)
    else if (!fs.readFileSync(p).equals(Buffer.from(want))) problems.push(`${rel}: stale`)
  }
  if (problems.length) {
    console.error('render chunks stale: ' + problems.join(', ') + '; run: cd tools/spa_precompile && npm run build')
    process.exit(1)
  }
  const gz = (await import('node:zlib')).gzipSync(files.get('app.render.js'), { level: 6 }).length
  console.log(`render chunks OK (root ${manifest.root.bytes}B gzip ${gz}B, ${Object.keys(manifest.groups).length} groups, ${Object.keys(manifest.pages).length} pages, vue ${compilerVersion})`)
  process.exit(0)
}

for (const [rel, text] of files) {
  const p = path.join(legacyDir, rel)
  fs.mkdirSync(path.dirname(p), { recursive: true })
  fs.writeFileSync(p, text)
}
const gz = (await import('node:zlib')).gzipSync(files.get('app.render.js'), { level: 6 }).length
console.log(`wrote app.render.js ${manifest.root.bytes}B (gzip ${gz}B) + ${Object.keys(manifest.groups).length} page chunks; root template ${manifest.root.templateSize}B`)
for (const [group, info] of Object.entries(manifest.groups)) {
  console.log(`  pages/${group}.render.js ${info.bytes}B (${info.pages.length} pages)`)
}
